<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('admin');$pdo=db();$year=active_academic_year();$selected=normalize_class_name((string)($_GET['kelas']??'1A'));if(!in_array($selected,all_class_names(),true))$selected='1A';$stmt=$pdo->prepare("SELECT s.*,u.full_name teacher_name,EXISTS(SELECT 1 FROM parent_student_links l WHERE l.student_id=s.id AND l.status='active') has_parent FROM students s LEFT JOIN users u ON u.id=s.teacher_id WHERE s.kelas=? ORDER BY s.nama_lengkap");$stmt->execute([$selected]);$students=$stmt->fetchAll();$teachers=$pdo->query("SELECT id,full_name FROM users WHERE role='guru' AND is_active=1 AND approval_status='approved' ORDER BY full_name")->fetchAll();$classStmt=$pdo->prepare('SELECT c.*,u.full_name teacher_name FROM classes c LEFT JOIN users u ON u.id=c.teacher_id WHERE c.nama_kelas=? AND c.tahun_ajaran=?');$classStmt->execute([$selected,$year]);$class=$classStmt->fetch();$recapStmt=$pdo->prepare("SELECT c.nama_kelas,u.full_name teacher_name,COUNT(CASE WHEN s.status='aktif' THEN 1 END) total,SUM(CASE WHEN s.status='aktif' AND s.level=1 THEN 1 ELSE 0 END) l1,SUM(CASE WHEN s.status='aktif' AND s.level=2 THEN 1 ELSE 0 END) l2,SUM(CASE WHEN s.status='aktif' AND s.level=3 THEN 1 ELSE 0 END) l3,SUM(CASE WHEN s.status='aktif' AND s.level=4 THEN 1 ELSE 0 END) l4,SUM(CASE WHEN s.status='aktif' AND s.level=5 THEN 1 ELSE 0 END) l5,SUM(CASE WHEN s.status='aktif' AND s.level=6 THEN 1 ELSE 0 END) l6,SUM(CASE WHEN s.status='aktif' AND s.level=7 THEN 1 ELSE 0 END) l7,SUM(CASE WHEN s.status='aktif' AND s.level=8 THEN 1 ELSE 0 END) l8,SUM(CASE WHEN s.status='aktif' AND s.level=9 THEN 1 ELSE 0 END) l9 FROM classes c LEFT JOIN users u ON u.id=c.teacher_id LEFT JOIN students s ON s.kelas=c.nama_kelas WHERE c.tahun_ajaran=? GROUP BY c.id,u.full_name ORDER BY c.tingkat,c.rombel");$recapStmt->execute([$year]);$recap=$recapStmt->fetchAll();$scores=$pdo->prepare('SELECT t.*,s.nama_lengkap FROM laporan_tahsin_tahfidz t JOIN students s ON s.id=t.student_id WHERE s.kelas=? AND t.tahun_ajaran=? ORDER BY t.tanggal DESC LIMIT 200');$scores->execute([$selected,$year]);$scoreRows=$scores->fetchAll();$pageTitle='Siswa & Kelas';require ROOT_PATH.'/includes/header.php';?>
<section class="card" style="padding:0;overflow:hidden;margin-bottom:20px"><div class="filter-row" style="padding:18px 20px"><div><h2 class="card-title" style="margin:0">Rekap Kelas 1A–6B</h2><small class="muted">Tahun ajaran <?= e($year) ?> · distribusi sembilan level Tahfidz</small></div></div><div class="table-wrap borderless"><table class="table class-recap-table"><thead><tr><th>Kelas</th><?php for($level=1;$level<=9;$level++):?><th><?= $level<=6?'Level '.$level:'Mustawa '.($level-6) ?></th><?php endfor;?><th>Total</th><th>Wali Kelas</th></tr></thead><tbody><?php foreach($recap as $row):?><tr class="<?= $row['nama_kelas']===$selected?'selected':'' ?>"><td><a class="class-pill" href="<?= url('admin/students-classes.php?kelas='.$row['nama_kelas']) ?>"><?= e($row['nama_kelas']) ?></a></td><?php for($level=1;$level<=9;$level++):?><td><?= (int)$row['l'.$level]?:'-' ?></td><?php endfor;?><td><strong><?= (int)$row['total'] ?></strong></td><td><?= e($row['teacher_name']?:'-') ?></td></tr><?php endforeach;?></tbody></table></div></section>
<div class="page-head"><div><p class="eyebrow">Data Sekolah</p><h1 class="page-title">Manajemen Siswa & Kelas</h1><p class="page-description">Lihat anggota kelas, wali kelas mengaji, status siswa, nilai per surat, dan laporan harian.</p></div></div><section class="card"><div class="filter-row"><div class="class-buttons"><?php foreach(all_class_names() as $name):?><a class="class-button <?= $name===$selected?'active':'' ?>" href="<?= url('admin/students-classes.php?kelas='.$name) ?>"><?= $name ?></a><?php endforeach;?></div><form action="<?= url('api/classes/index.php') ?>" method="post" data-ajax class="actions"><?= csrf_field() ?><input type="hidden" name="action" value="assign_teacher"><input type="hidden" name="kelas" value="<?= e($selected) ?>"><select class="select" name="teacher_id"><option value="">Belum ada wali mengaji</option><?php foreach($teachers as $teacher):?><option value="<?= e($teacher['id']) ?>" <?= ($class['teacher_id']??'')===$teacher['id']?'selected':'' ?>><?= e($teacher['full_name']) ?></option><?php endforeach;?></select><button class="btn btn-primary" type="submit">Simpan Wali Kelas</button></form></div></section><section class="card" style="margin-top:20px"><div class="filter-row"><div><p class="eyebrow">Anggota Kelas</p><h2 style="font-size:28px;margin:2px 0">Kelas <?= e($selected) ?></h2><span class="muted"><?= count($students) ?> siswa · Wali mengaji: <?= e($class['teacher_name']??'Belum ditentukan') ?></span></div><input class="input" data-search-table="#students-table" placeholder="Cari siswa atau NIS..."></div><div class="table-wrap"><table class="table" id="students-table"><thead><tr><th>Siswa</th><th>Guru</th><th>Kelas</th><th>Level</th><th>Orang Tua</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($students as $student):?><tr><td><span class="name"><?= e($student['nama_lengkap']) ?></span><br><small class="muted">NIS <?= e($student['nis']) ?></small></td><td><?= e($student['teacher_name']??'Belum ditentukan') ?></td><td><span class="badge badge-blue"><?= e($student['kelas']) ?></span></td><td><?= e(level_name($student['level'])) ?></td><td><span class="badge <?= $student['has_parent']?'badge-green':'badge-yellow' ?>"><?= $student['has_parent']?'Terhubung':'Belum ada' ?></span></td><td><span class="badge <?= $student['status']==='aktif'?'badge-green':'badge-gray' ?>"><?= e(str_replace('_',' ',$student['status'])) ?></span></td><td><form action="<?= url('api/students/index.php') ?>" method="post" data-ajax class="actions"><?= csrf_field() ?><input type="hidden" name="action" value="status"><input type="hidden" name="student_id" value="<?= e($student['id']) ?>"><select class="select" name="status"><?php foreach(['aktif','tidak_aktif','pindah','lulus'] as $status):?><option <?= $status===$student['status']?'selected':'' ?>><?= $status ?></option><?php endforeach;?></select><button class="btn btn-soft btn-sm">Simpan</button></form></td></tr><?php endforeach;?><?php if(!$students):?><tr><td colspan="7"><div class="empty"><strong>Belum ada siswa di kelas <?= e($selected) ?></strong>Impor atau tambahkan siswa melalui role Guru.</div></td></tr><?php endif;?></tbody></table></div></section><section class="card" style="margin-top:20px"><div class="filter-row"><h2 class="card-title">Nilai per Surat · Kelas <?= e($selected) ?></h2><span class="badge badge-green"><?= count($scoreRows) ?> catatan</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Siswa</th><th>Surat</th><th>Kelancaran</th><th>Makhraj</th><th>Tajwid</th><th>Sambung Ayat</th><th>Rata-rata</th></tr></thead><tbody><?php foreach($scoreRows as $score):?><tr><td><?= e(format_date_id($score['tanggal'])) ?></td><td class="name"><?= e($score['nama_lengkap']) ?></td><td><?= e($score['nama_surah']) ?></td><td><?= e((string)$score['nilai_kelancaran']) ?></td><td><?= e((string)$score['nilai_makhraj']) ?></td><td><?= e((string)$score['nilai_tajwid']) ?></td><td><?= e((string)$score['nilai_hafalan']) ?></td><td><strong><?= e((string)$score['nilai_rata_rata']) ?></strong></td></tr><?php endforeach;?><?php if(!$scoreRows):?><tr><td colspan="8"><div class="empty"><strong>Belum ada nilai kelas ini</strong>Nilai Guru akan tampil otomatis.</div></td></tr><?php endif;?></tbody></table></div></section><?php require ROOT_PATH.'/includes/footer.php';?>
